package com.sanctuarygames.createtransit.radio;
import com.sanctuarygames.createtransit.elevator.*;import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.neoforged.neoforge.network.PacketDistributor;import net.minecraft.server.level.ServerPlayer;
public final class SpeakerMenu extends AbstractContainerMenu {
 public final BlockPos pos;private final Player player;private final StationSpeakerEntity speaker;private CompoundTag state,last;private long actionTick=Long.MIN_VALUE;
 public SpeakerMenu(int id,Inventory inv,RegistryFriendlyByteBuf b){this(id,inv,b.readBlockPos(),b.readNbt(),null);}
 public SpeakerMenu(int id,Inventory inv,StationSpeakerEntity e){this(id,inv,e.getBlockPos(),e.snapshot(),e);}
 private SpeakerMenu(int id,Inventory inv,BlockPos pos,CompoundTag t,StationSpeakerEntity e){super(RadioRegistry.SPEAKER_MENU.get(),id);this.pos=pos;player=inv.player;speaker=e;accept(t);}
 public CompoundTag state(){return state;}public void accept(CompoundTag t){state=t==null?new CompoundTag():t.copy();}
 @Override public boolean stillValid(Player p){return speaker==null||!speaker.isRemoved()&&p.level()==speaker.getLevel()&&p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(pos))<=64;}
 public void action(Player p,ElevatorPackets.Action a){if(speaker==null||p!=player||p.containerMenu!=this||a.menuId()!=containerId||!p.mayBuild()||!stillValid(p)||actionTick==p.level().getGameTime())return;actionTick=p.level().getGameTime();try{if(a.operation()==12)RadioStations.get((net.minecraft.server.level.ServerLevel)p.level()).add((ServerPlayer)p,a.first(),a.second());else if(a.operation()==14)RadioStations.get((net.minecraft.server.level.ServerLevel)p.level()).remove((ServerPlayer)p,a.second());else if(a.operation()==13){var data=RadioStations.get((net.minecraft.server.level.ServerLevel)p.level());String key=a.first(),value=a.second();if(key.equals("group")){if(!value.isBlank())data.group(value,speaker.radio);speaker.group=value;}else if(key.startsWith("group.")){if(speaker.group.isBlank())throw new IllegalArgumentException("Join a radio group first");String k=key.substring(6);if(!java.util.Set.of("enabled","station","volume","mode").contains(k))throw new IllegalArgumentException("Invalid group setting");data.group(speaker.group,speaker.radio).configure(k,value);data.setDirty();}else if(key.equals("primary")||key.equals("secondary")){int color=Integer.parseInt(value);if(color<0||color>15)throw new IllegalArgumentException("Invalid dye");if(key.equals("primary"))speaker.primary=color;else speaker.secondary=color;p.level().sendBlockUpdated(pos,speaker.getBlockState(),speaker.getBlockState(),3);}else speaker.radio.configure(key,value);}else return;speaker.setChanged();broadcastChanges();}catch(IllegalArgumentException ex){ElevatorFeedback.error(p,ex.getMessage());}}
 @Override public void broadcastChanges(){super.broadcastChanges();if(speaker!=null&&player instanceof ServerPlayer p){var t=speaker.snapshot();if(!t.equals(last)){accept(t);last=t.copy();PacketDistributor.sendToPlayer(p,new ElevatorPackets.Snapshot(containerId,t));}}}
 @Override public ItemStack quickMoveStack(Player p,int index){return ItemStack.EMPTY;}
}
